create extension if not exists pgcrypto;
create table public.routers (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade default auth.uid(), name text not null check (char_length(name) between 2 and 80), description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sync_devices (id uuid primary key default gen_random_uuid(), router_id uuid not null references public.routers(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, label text not null default 'Android worker', token_hash text not null unique, created_at timestamptz not null default now(), last_seen_at timestamptz, revoked_at timestamptz);
create table public.sync_runs (id uuid primary key default gen_random_uuid(), router_id uuid not null references public.routers(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, device_id uuid references public.sync_devices(id) on delete set null, mode text not null check (mode in ('bootstrap','incremental')), status text not null check (status in ('running','success','error')), users_count integer not null default 0, profiles_count integer not null default 0, session_rows_count integer not null default 0, message text, started_at timestamptz not null default now(), finished_at timestamptz);
create table public.report_profiles (id bigint generated always as identity primary key, router_id uuid not null references public.routers(id) on delete cascade, run_id uuid not null references public.sync_runs(id) on delete cascade, name text not null, price numeric not null default 0, validity text not null default '');
create table public.report_users (id bigint generated always as identity primary key, router_id uuid not null references public.routers(id) on delete cascade, run_id uuid not null references public.sync_runs(id) on delete cascade, username text not null, profile text not null default '', price numeric not null default 0, first_name text not null default '', comment text not null default '', nas_port text not null default '', nas_port_id text not null default '', calling_station_id text not null default '', called_station_id text not null default '', last_seen text not null default '', bytes_in bigint not null default 0, bytes_out bigint not null default 0, uptime text not null default '', disabled boolean not null default false);
create unique index report_users_run_username on public.report_users(run_id,username); create index report_users_run_search on public.report_users(run_id,username); create index report_users_run_profile on public.report_users(run_id,profile); create index sync_runs_router_status on public.sync_runs(router_id,status,finished_at desc);
create table public.report_snapshots (router_id uuid primary key references public.routers(id) on delete cascade, owner_id uuid not null references auth.users(id) on delete cascade, active_run_id uuid references public.sync_runs(id) on delete set null, updated_at timestamptz not null default now());
alter table public.routers enable row level security; alter table public.sync_devices enable row level security; alter table public.sync_runs enable row level security; alter table public.report_profiles enable row level security; alter table public.report_users enable row level security; alter table public.report_snapshots enable row level security;
create policy "owners manage routers" on public.routers for all using (owner_id=auth.uid()) with check (owner_id=auth.uid());
create policy "owners read devices" on public.sync_devices for select using (owner_id=auth.uid());
create policy "owners read runs" on public.sync_runs for select using (owner_id=auth.uid());
create policy "owners read profiles" on public.report_profiles for select using (exists(select 1 from public.routers r where r.id=router_id and r.owner_id=auth.uid()));
create policy "owners read users" on public.report_users for select using (exists(select 1 from public.routers r where r.id=router_id and r.owner_id=auth.uid()));
create policy "owners read snapshots" on public.report_snapshots for select using (owner_id=auth.uid());
